// [S4] Three-portal family features — Head-only join-request review.
// [S1] Invitations addressed to this account appear above the list (whole-project waiver 2026-09-28b).
import 'package:family_veda/providers/family_portal_provider.dart';
import 'package:family_veda/widgets/family/incoming_invitations_section.dart';
import 'package:family_veda/widgets/shared/async_state_views.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

class JoinRequestsScreen extends ConsumerWidget {
  const JoinRequestsScreen({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) => Scaffold(
    appBar: AppBar(title: const Text('Join requests')),
    body: SafeArea(
      child: Column(
        children: [
          const IncomingInvitationsSection(),
          Expanded(
            child: ref
                  .watch(familyDashboardProvider)
                  .when(
                    loading: () => const LoadingStateView(label: 'Loading requests'),
                    error: (_, _) => ErrorRetryView(
                      onRetry: () => ref.invalidate(familyDashboardProvider),
                    ),
                    data: (dashboard) {
                      final familyId = dashboard.familyId;
                      if (familyId == null) {
                        return const EmptyStateView(
                          title: 'No family found',
                          message: 'Join or create a family first.',
                        );
                      }
                      return _JoinRequestsList(familyId: familyId);
                    },
                  ),
          ),
        ],
      ),
    ),
  );
}

class _JoinRequestsList extends ConsumerWidget {
  const _JoinRequestsList({required this.familyId});

  final String familyId;

  Future<void> _respond(
    BuildContext context,
    WidgetRef ref,
    String requestId,
    bool accept,
  ) async {
    try {
      final api = ref.read(familyPortalApiProvider);
      if (accept) {
        await api.acceptJoinRequest(requestId);
      } else {
        await api.declineJoinRequest(requestId);
      }
      ref.invalidate(pendingJoinRequestsProvider(familyId));
      ref.invalidate(familyDashboardProvider);
      if (context.mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text(accept ? 'Request approved.' : 'Request declined.')),
        );
      }
    } on Object {
      if (context.mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Could not update this request. Try again.')),
        );
      }
    }
  }

  @override
  Widget build(BuildContext context, WidgetRef ref) => ref
      .watch(pendingJoinRequestsProvider(familyId))
      .when(
        loading: () => const LoadingStateView(label: 'Loading requests'),
        error: (_, _) => ErrorRetryView(
          onRetry: () => ref.invalidate(pendingJoinRequestsProvider(familyId)),
        ),
        data: (items) => items.isEmpty
            ? const EmptyStateView(
                title: 'No pending requests',
                message: 'New requests to join your family will appear here.',
              )
            : ListView.builder(
                padding: const EdgeInsets.all(16),
                itemCount: items.length,
                itemBuilder: (context, index) {
                  final item = items[index];
                  return Card(
                    child: Padding(
                      padding: const EdgeInsets.all(12),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            item.requesterDisplayName ?? 'Family member',
                            style: const TextStyle(fontWeight: FontWeight.w700),
                          ),
                          Text(item.requesterEmailMasked ?? ''),
                          const SizedBox(height: 4),
                          Text('Relationship: ${item.relationshipType}'),
                          if (item.message != null && item.message!.isNotEmpty)
                            Padding(
                              padding: const EdgeInsets.only(top: 4),
                              child: Text('"${item.message}"'),
                            ),
                          const SizedBox(height: 8),
                          Row(
                            mainAxisAlignment: MainAxisAlignment.end,
                            children: [
                              TextButton(
                                onPressed: () => _respond(context, ref, item.id, false),
                                child: const Text('Decline'),
                              ),
                              const SizedBox(width: 8),
                              ElevatedButton(
                                onPressed: () => _respond(context, ref, item.id, true),
                                child: const Text('Accept'),
                              ),
                            ],
                          ),
                        ],
                      ),
                    ),
                  );
                },
              ),
      );
}
